// mini markdown parser (offline) — covers what ygiaphan posts use
// exposes window.marked.parse(md)
(function(){
  function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function inline(s){
    s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g,'<img src="$2" alt="$1">');
    s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>');
    s = s.replace(/\*\*([^\*]+)\*\*/g,'<strong>$1</strong>');
    s = s.replace(/(^|[^\*])\*([^\*\n]+)\*/g,'$1<em>$2</em>');
    s = s.replace(/`([^`]+)`/g,'<code>$1</code>');
    return s;
  }
  function parse(md){
    md = md.replace(/\r\n?/g,'\n');
    const lines = md.split('\n');
    const out = [];
    let i = 0;
    while (i < lines.length){
      let ln = lines[i];

      // fenced code
      if (/^```/.test(ln)){
        const lang = ln.slice(3).trim();
        const buf = [];
        i++;
        while (i < lines.length && !/^```/.test(lines[i])){ buf.push(esc(lines[i])); i++; }
        i++;
        out.push(`<pre><code${lang?` class="lang-${lang}"`:''}>${buf.join('\n')}</code></pre>`);
        continue;
      }

      // headings
      let m;
      if (m = ln.match(/^(#{1,6})\s+(.+)$/)){ out.push(`<h${m[1].length}>${inline(m[2])}</h${m[1].length}>`); i++; continue; }

      // blockquote (group consecutive)
      if (/^>\s?/.test(ln)){
        const buf = [];
        while (i < lines.length && /^>\s?/.test(lines[i])){ buf.push(lines[i].replace(/^>\s?/,'')); i++; }
        out.push(`<blockquote>${inline(buf.join(' '))}</blockquote>`);
        continue;
      }

      // table: header row + separator
      if (/^\|.*\|\s*$/.test(ln) && i+1 < lines.length && /^\|?\s*[-:]+(\s*\|\s*[-:]+)+\s*\|?\s*$/.test(lines[i+1])){
        const head = ln.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(c=>c.trim());
        i += 2;
        const rows = [];
        while (i < lines.length && /^\|.*\|\s*$/.test(lines[i])){
          rows.push(lines[i].trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(c=>c.trim()));
          i++;
        }
        out.push('<table><thead><tr>'+head.map(c=>`<th>${inline(c)}</th>`).join('')+'</tr></thead><tbody>'+
          rows.map(r=>'<tr>'+r.map(c=>`<td>${inline(c)}</td>`).join('')+'</tr>').join('')+'</tbody></table>');
        continue;
      }

      // unordered list
      if (/^\s*[-*+]\s+/.test(ln)){
        const buf = [];
        while (i < lines.length && /^\s*[-*+]\s+/.test(lines[i])){
          buf.push(`<li>${inline(lines[i].replace(/^\s*[-*+]\s+/,''))}</li>`);
          i++;
        }
        out.push(`<ul>${buf.join('')}</ul>`); continue;
      }

      // ordered list
      if (/^\s*\d+\.\s+/.test(ln)){
        const buf = [];
        while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])){
          buf.push(`<li>${inline(lines[i].replace(/^\s*\d+\.\s+/,''))}</li>`);
          i++;
        }
        out.push(`<ol>${buf.join('')}</ol>`); continue;
      }

      // blank line
      if (ln.trim() === ''){ i++; continue; }

      // paragraph (collect until blank)
      const buf = [ln];
      i++;
      while (i < lines.length && lines[i].trim() !== '' && !/^(#{1,6}\s|>|\s*[-*+]\s|\s*\d+\.\s|```|\|)/.test(lines[i])){
        buf.push(lines[i]); i++;
      }
      out.push(`<p>${inline(buf.join(' '))}</p>`);
    }
    return out.join('\n');
  }
  window.marked = { parse };
})();
